INSERT INTO jlas_compiled_variant_n5 (item_id,rank_no,normalized_expression,normalized_reading) SELECT item_id,1,normalized_expression,normalized_reading FROM jlas_compiled_word_n5 WHERE item_id>0;
INSERT INTO vocabulary_entry (expression,normalized_expression,reading,normalized_reading,meaning,jlpt_level,example_ja,example_vi,usage_scope,dictionary_status) SELECT w.expression,w.normalized_expression,w.reading,w.normalized_reading,w.meaning,'N5',w.example_ja,w.example_vi,'TEXTBOOK','DRAFT' FROM jlas_compiled_word_n5 w WHERE NOT EXISTS (SELECT 1 FROM jlas_compiled_variant_n5 v JOIN vocabulary_entry e ON e.normalized_expression=v.normalized_expression AND e.normalized_reading=v.normalized_reading WHERE v.item_id=w.item_id) ORDER BY w.section_id,w.order_index;
UPDATE jlas_compiled_word_n5 w SET w.vocab_id=(SELECT e.id FROM jlas_compiled_variant_n5 v JOIN vocabulary_entry e ON e.normalized_expression=v.normalized_expression AND e.normalized_reading=v.normalized_reading WHERE v.item_id=w.item_id ORDER BY v.rank_no LIMIT 1) WHERE w.item_id>0;
INSERT INTO content_item (id,section_id,content_type,title,content,order_index) SELECT w.item_id,w.section_id,'READING',w.expression,w.expression,w.order_index FROM jlas_compiled_word_n5 w ORDER BY w.item_id ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),title=VALUES(title),content=VALUES(content),order_index=VALUES(order_index);
INSERT INTO content_vocabulary (content_item_id,vocabulary_id,learning_meaning_vi,learning_example_ja,learning_example_vi) SELECT w.item_id,w.vocab_id,w.meaning,IF(w.example_ja IS NULL,e.example_ja,w.example_ja),IF(w.example_ja IS NULL,e.example_vi,w.example_vi) FROM jlas_compiled_word_n5 w JOIN vocabulary_entry e ON e.id=w.vocab_id ORDER BY w.item_id ON DUPLICATE KEY UPDATE learning_meaning_vi=VALUES(learning_meaning_vi),learning_example_ja=VALUES(learning_example_ja),learning_example_vi=VALUES(learning_example_vi);
DELETE cv FROM content_vocabulary cv JOIN jlas_compiled_word_n5 w ON w.item_id=cv.content_item_id WHERE cv.vocabulary_id<>w.vocab_id;
